<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/bootstrap.php';
$user=require_auth();$pdo=db();$error=null;$success=null;
function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
function manager(array $u):bool{return in_array($u['role'],['teacher','admin'],true);}
function admin_only(array $u):bool{return $u['role']==='admin';}
function pg(string $p):string{return '/panel/?page='.rawurlencode($p);}
function role_label(string $r):string{return ['admin'=>'مدیر','teacher'=>'مدرس','student'=>'دانش‌آموز'][$r]??$r;}
$hasStarts=(bool)$pdo->query("SHOW COLUMNS FROM classes LIKE 'starts_at'")->fetch();$hasGuest=(bool)$pdo->query("SHOW COLUMNS FROM classes LIKE 'allow_guest'")->fetch();$hasUsers=(bool)$pdo->query("SHOW COLUMNS FROM classes LIKE 'show_users'")->fetch();$hasChat=(bool)$pdo->query("SHOW COLUMNS FROM classes LIKE 'show_chat'")->fetch();$hasAllowed=(bool)$pdo->query("SHOW TABLES LIKE 'class_allowed_users'")->fetch();$hasRequests=(bool)$pdo->query("SHOW TABLES LIKE 'class_join_requests'")->fetch();$hasCreatedBy=(bool)$pdo->query("SHOW COLUMNS FROM users LIKE 'created_by'")->fetch();
$page=(string)($_GET['page']??'dashboard');$pages=['dashboard','create_student','students','classes','create_class','create_access','requests','admins','ads'];if(!in_array($page,$pages,true))$page='dashboard';if(!manager($user)&&$page!=='dashboard')$page='dashboard';if(!admin_only($user)&&$page==='admins')$page='dashboard';
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$a=(string)($_POST['action']??'');
 if($a==='create_student'){require_teacher();$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$pass=(string)($_POST['password']??'');if(mb_strlen($name)<2||mb_strlen($name)>100)throw new InvalidArgumentException('نام دانش‌آموز معتبر نیست.');if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('ایمیل معتبر نیست.');if(strlen($pass)<8)throw new InvalidArgumentException('رمز عبور حداقل ۸ کاراکتر باشد.');$q=$pdo->prepare('SELECT id FROM users WHERE email=?');$q->execute([$email]);if($q->fetch())throw new InvalidArgumentException('این ایمیل قبلاً ثبت شده است.');if($hasCreatedBy){$pdo->prepare("INSERT INTO users(name,email,password,role,created_by,created_at,updated_at) VALUES(?,?,?,'student',?,NOW(),NOW())")->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),$user['id']]);}else{$pdo->prepare("INSERT INTO users(name,email,password,role,created_at,updated_at) VALUES(?,?,?,'student',NOW(),NOW())")->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);}$success='دانش‌آموز ساخته شد.';$page='students';}
 if($a==='create_class'){require_teacher();$title=trim((string)($_POST['title']??''));$desc=trim((string)($_POST['description']??''));$starts=trim((string)($_POST['starts_at']??''));$duration=max(15,min(1440,(int)($_POST['duration']??60)));$guest=$hasGuest&&!empty($_POST['allow_guest'])?1:0;$su=$hasUsers&&!empty($_POST['show_users'])?1:0;$sc=$hasChat&&!empty($_POST['show_chat'])?1:0;if($title==='')throw new InvalidArgumentException('عنوان کلاس را وارد کنید.');$ts=$hasStarts?strtotime($starts):time();if(!$ts||$ts<time()-60)throw new InvalidArgumentException('زمان کلاس را درست وارد کنید.');do{$code=strtoupper(bin2hex(random_bytes(4)));$q=$pdo->prepare('SELECT id FROM classes WHERE room_code=?');$q->execute([$code]);}while($q->fetch());$start=date('Y-m-d H:i:s',$ts);$exp=date('Y-m-d H:i:s',$ts+$duration*60);$cols='teacher_id,title,description,room_code,status,expires_at';$vals='?,?,?,?,\'scheduled\',?';$params=[$user['id'],$title,$desc?:null,$code,$exp];if($hasGuest){$cols.=',allow_guest';$vals.=',?';$params[]=$guest;}if($hasStarts){$cols.=',starts_at';$vals.=',?';$params[]=$start;}if($hasUsers){$cols.=',show_users';$vals.=',?';$params[]=$su;}if($hasChat){$cols.=',show_chat';$vals.=',?';$params[]=$sc;}$pdo->prepare("INSERT INTO classes($cols) VALUES($vals)")->execute($params);$success='کلاس ساخته شد. کد: '.$code;$page='classes';}
 if($a==='edit_class'){require_teacher();$id=(int)$_POST['class_id'];$title=trim((string)$_POST['title']);$desc=trim((string)$_POST['description']);$set='title=?,description=?';$p=[$title,$desc?:null];if($hasStarts&&trim((string)$_POST['starts_at'])!==''){$x=strtotime((string)$_POST['starts_at']);if(!$x)throw new InvalidArgumentException('زمان شروع معتبر نیست.');$set.=',starts_at=?';$p[]=date('Y-m-d H:i:s',$x);}if(trim((string)$_POST['expires_at'])!==''){$x=strtotime((string)$_POST['expires_at']);if(!$x)throw new InvalidArgumentException('زمان پایان معتبر نیست.');$set.=',expires_at=?';$p[]=date('Y-m-d H:i:s',$x);}if($hasGuest){$set.=',allow_guest=?';$p[]=!empty($_POST['allow_guest'])?1:0;}if($hasUsers){$set.=',show_users=?';$p[]=!empty($_POST['show_users'])?1:0;}if($hasChat){$set.=',show_chat=?';$p[]=!empty($_POST['show_chat'])?1:0;}$p[]=$id;if($user['role']!=='admin'){$set.=',updated_at=NOW()';$p[]=$user['id'];$where='id=? AND teacher_id=?';}else{$set.=',updated_at=NOW()';$where='id=?';}$pdo->prepare("UPDATE classes SET $set WHERE $where")->execute($p);$success='تنظیمات کلاس ذخیره شد.';$page='classes';}
 if($a==='delete_class'){require_teacher();$id=(int)$_POST['class_id'];$q=$user['role']==='admin'?$pdo->prepare('DELETE FROM classes WHERE id=?'):$pdo->prepare('DELETE FROM classes WHERE id=? AND teacher_id=?');$user['role']==='admin'?$q->execute([$id]):$q->execute([$id,$user['id']]);$success='کلاس حذف شد.';$page='classes';}
 if($a==='create_access'){require_teacher();if(!$hasAllowed)throw new RuntimeException('جدول کاربران مجاز ساخته نشده است.');$cid=(int)$_POST['class_id'];$uid=(int)$_POST['user_id'];$q=$user['role']==='admin'?$pdo->prepare('SELECT id,title FROM classes WHERE id=?'):$pdo->prepare('SELECT id,title FROM classes WHERE id=? AND teacher_id=?');$user['role']==='admin'?$q->execute([$cid]):$q->execute([$cid,$user['id']]);$c=$q->fetch();if(!$c)throw new RuntimeException('دسترسی به این کلاس ندارید.');$q=$pdo->prepare("SELECT id,name,email,role FROM users WHERE id=?");$q->execute([$uid]);$t=$q->fetch();if(!$t||$t['role']!=='student')throw new InvalidArgumentException('فقط دانش‌آموز را می‌توان مجاز کرد.');$pdo->prepare("INSERT INTO class_allowed_users(class_id,user_id,email,created_at,updated_at) VALUES(?,?,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE email=VALUES(email),updated_at=NOW()")->execute([$cid,$uid,$t['email']]);$success='اجازه ورود به «'.$t['name'].'» برای «'.$c['title'].'» داده شد.';$page='create_access';}
 if($a==='remove_allowed'){require_teacher();$id=(int)$_POST['allowed_id'];$q=$user['role']==='admin'?$pdo->prepare('DELETE FROM class_allowed_users WHERE id=?'):$pdo->prepare('DELETE cau FROM class_allowed_users cau JOIN classes c ON c.id=cau.class_id WHERE cau.id=? AND c.teacher_id=?');$user['role']==='admin'?$q->execute([$id]):$q->execute([$id,$user['id']]);$success='دسترسی حذف شد.';$page='create_access';}
 if($a==='approve_request'||$a==='reject_request'){require_teacher();if(!$hasRequests)throw new RuntimeException('جدول درخواست‌ها ساخته نشده است.');$rid=(int)$_POST['request_id'];$q=$pdo->prepare('SELECT r.*,c.teacher_id FROM class_join_requests r JOIN classes c ON c.id=r.class_id WHERE r.id=?');$q->execute([$rid]);$r=$q->fetch();if(!$r||($user['role']!=='admin'&&(int)$r['teacher_id']!==(int)$user['id']))throw new RuntimeException('دسترسی ندارید.');if($a==='approve_request'){$pdo->beginTransaction();$pdo->prepare("UPDATE class_join_requests SET status='approved',decided_by=?,decided_at=NOW(),reject_reason=NULL WHERE id=?")->execute([$user['id'],$rid]);$pdo->prepare("INSERT INTO class_participants(class_id,user_id,role,joined_at,left_at,created_at,updated_at) VALUES(?,?, 'student',NOW(),NULL,NOW(),NOW()) ON DUPLICATE KEY UPDATE role='student',joined_at=NOW(),left_at=NULL,updated_at=NOW()")->execute([(int)$r['class_id'],(int)$r['user_id']]);$pdo->commit();$success='درخواست تأیید شد.';}else{$pdo->prepare("UPDATE class_join_requests SET status='rejected',decided_by=?,decided_at=NOW() WHERE id=?")->execute([$user['id'],$rid]);$success='درخواست رد شد.';}$page='requests';}
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof InvalidArgumentException?$e->getMessage():'عملیات انجام نشد.';}}
$classes=[];$students=[];$allowed=[];$requests=[];$admins=[];$edit=null;$ads=[];
if(manager($user)){if($user['role']==='admin')$classes=$pdo->query("SELECT c.*,u.name teacher_name FROM classes c JOIN users u ON u.id=c.teacher_id ORDER BY c.created_at DESC")->fetchAll();else{$q=$pdo->prepare("SELECT c.*,u.name teacher_name FROM classes c JOIN users u ON u.id=c.teacher_id WHERE c.teacher_id=? ORDER BY c.created_at DESC");$q->execute([$user['id']]);$classes=$q->fetchAll();}
 if($user['role']==='admin'){$students=$pdo->query("SELECT id,name,email,created_at FROM users WHERE role='student' ORDER BY name")->fetchAll();}elseif($hasCreatedBy){$q=$pdo->prepare("SELECT DISTINCT u.id,u.name,u.email,u.created_at FROM users u LEFT JOIN class_participants cp ON cp.user_id=u.id LEFT JOIN classes c ON c.id=cp.class_id AND c.teacher_id=? WHERE u.role='student' AND (c.id IS NOT NULL OR u.created_by=?) ORDER BY u.name");$q->execute([$user['id'],$user['id']]);$students=$q->fetchAll();}else{$q=$pdo->prepare("SELECT DISTINCT u.id,u.name,u.email,u.created_at FROM users u JOIN class_participants cp ON cp.user_id=u.id JOIN classes c ON c.id=cp.class_id WHERE u.role='student' AND c.teacher_id=? ORDER BY u.name");$q->execute([$user['id']]);$students=$q->fetchAll();}
 if($hasAllowed){$sql="SELECT cau.*,c.title,c.room_code,u.name student_name FROM class_allowed_users cau JOIN classes c ON c.id=cau.class_id JOIN users u ON u.id=cau.user_id".($user['role']==='admin'?'':' WHERE c.teacher_id='.((int)$user['id'])).' ORDER BY cau.id DESC';$allowed=$pdo->query($sql)->fetchAll();}if($hasRequests){$sql="SELECT r.*,c.title,c.room_code,u.name student_name,u.email student_email FROM class_join_requests r JOIN classes c ON c.id=r.class_id JOIN users u ON u.id=r.user_id WHERE r.status='pending'".($user['role']==='admin'?'':' AND c.teacher_id='.((int)$user['id'])).' ORDER BY r.requested_at DESC';$requests=$pdo->query($sql)->fetchAll();}if(admin_only($user))$admins=$pdo->query("SELECT id,name,email,created_at FROM users WHERE role='admin' ORDER BY name")->fetchAll();}
if($page==='classes'&&isset($_GET['edit'])){$id=(int)$_GET['edit'];$q=$user['role']==='admin'?$pdo->prepare('SELECT * FROM classes WHERE id=?'):$pdo->prepare('SELECT * FROM classes WHERE id=? AND teacher_id=?');$user['role']==='admin'?$q->execute([$id]):$q->execute([$id,$user['id']]);$edit=$q->fetch()?:null;}try{$ads=$pdo->query('SELECT * FROM advertisements ORDER BY active DESC,id DESC')->fetchAll();}catch(Throwable $e){}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>پنل | کاداد کلاس</title><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link href="https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;600;700;800;900&display=swap" rel="stylesheet"><style>:root{--p:#635bff;--t:#101828;--m:#667085;--b:#e4e7ec;--bg:#f6f7fb;--s:#0b1020}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--t);font-family:Vazirmatn,Tahoma,sans-serif}.app{min-height:100vh;display:flex}.side{width:250px;background:var(--s);color:#fff;padding:18px 13px;position:sticky;top:0;height:100vh;display:flex;flex-direction:column}.brand{display:flex;gap:10px;align-items:center;color:#fff;text-decoration:none;font-weight:900;padding:8px 10px 22px}.logo{width:40px;height:40px;border-radius:12px;background:linear-gradient(135deg,#766cff,#5148e8);display:grid;place-items:center}.nav{display:flex;flex-direction:column;gap:4px}.nav a{color:#b9c2d3;text-decoration:none;padding:11px 12px;border-radius:10px;font-size:13px;font-weight:700}.nav a:hover,.nav a.active{background:#1a2340;color:#fff}.sep{height:1px;background:#27314a;margin:9px}.logout{margin-top:auto;color:#cbd5e1;background:#151d32;border-radius:10px;padding:10px;text-align:center;text-decoration:none;font-size:12px;font-weight:800}.main{flex:1;min-width:0;padding:28px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.top h1{margin:0;font-size:27px}.top p{margin:5px 0 0;color:var(--m);font-size:12px}.user{background:#fff;border:1px solid var(--b);padding:9px 12px;border-radius:11px;color:var(--m);font-size:12px}.card{background:#fff;border:1px solid var(--b);border-radius:17px;padding:19px;margin-bottom:16px;box-shadow:0 6px 22px rgba(16,24,40,.04)}.card h2{margin:0 0 15px;font-size:18px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:15px}.stat{font-size:30px;font-weight:900}.muted{color:var(--m);font-size:12px;line-height:1.9}.fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.full{grid-column:1/-1}label{display:block;font-size:12px;font-weight:800;margin-bottom:6px}input,textarea,select{width:100%;border:1px solid var(--b);border-radius:10px;padding:10px 12px;font:inherit;background:#fff}textarea{min-height:80px}.btn{display:inline-block;border:0;border-radius:10px;padding:10px 14px;background:var(--p);color:#fff;font:800 12px Vazirmatn;cursor:pointer;text-decoration:none}.secondary{background:#eef0ff;color:#4d45d8}.danger{background:#fff0f1;color:#be123c}.actions{display:flex;gap:7px;flex-wrap:wrap}.msg{padding:11px 13px;border-radius:11px;margin-bottom:14px;font-size:13px}.err{background:#fff1f2;color:#be123c}.ok{background:#ecfdf3;color:#027a48}.table{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{text-align:right;padding:10px 8px;border-bottom:1px solid var(--b);white-space:nowrap}th{color:var(--m);font-size:11px}.code{display:inline-block;background:#f1f2ff;color:#5148e8;border-radius:8px;padding:5px 8px;font-weight:900;letter-spacing:2px}.row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid var(--b)}.row:last-child{border-bottom:0}.check{display:flex;align-items:center;gap:8px;margin-top:8px;font-size:12px}.check input{width:auto}.note{font-size:11px;color:var(--m);margin-top:7px}@media(max-width:700px){.app{display:block}.side{width:100%;height:auto;position:static}.nav{display:grid;grid-template-columns:1fr 1fr}.logout{margin-top:14px}.main{padding:15px}.fields{grid-template-columns:1fr}.full{grid-column:auto}.top{flex-direction:column;align-items:flex-start;gap:10px}}</style></head><body><div class="app"><aside class="side"><a class="brand" href="/panel"><span class="logo">ک</span><span>کاداد کلاس</span></a><nav class="nav"><a class="<?= $page==='dashboard'?'active':'' ?>" href="<?=pg('dashboard')?>">🏠 داشبورد</a><?php if(manager($user)):?><a class="<?= $page==='create_student'?'active':'' ?>" href="<?=pg('create_student')?>">👨‍🎓 ساخت دانش‌آموز</a><a class="<?= $page==='students'?'active':'' ?>" href="<?=pg('students')?>">👥 دانش‌آموزان</a><a class="<?= in_array($page,['classes','create_class'],true)?'active':'' ?>" href="<?=pg('classes')?>">🏫 کلاس‌ها</a><a class="<?= $page==='create_access'?'active':'' ?>" href="<?=pg('create_access')?>">🔐 ساخت درخواست دسترسی</a><a class="<?= $page==='requests'?'active':'' ?>" href="<?=pg('requests')?>">📥 درخواست‌های ورود<?=count($requests)?' ('.count($requests).')':''?></a><a class="<?= $page==='ads'?'active':'' ?>" href="<?=pg('ads')?>">📢 تبلیغات</a><?php if(admin_only($user)):?><div class="sep"></div><a class="<?= $page==='admins'?'active':'' ?>" href="<?=pg('admins')?>">👑 مدیران</a><?php endif;?><?php endif;?></nav><a class="logout" href="/login/logout.php">خروج از حساب</a></aside><main class="main"><div class="top"><div><h1><?php $titles=['dashboard'=>'داشبورد','create_student'=>'ساخت دانش‌آموز','students'=>'دانش‌آموزان','classes'=>'کلاس‌ها','create_class'=>'ساخت کلاس','create_access'=>'ساخت درخواست دسترسی','requests'=>'درخواست‌های ورود','admins'=>'مدیران','ads'=>'تبلیغات'];echo h($titles[$page]??'پنل');?></h1><p><?=h($user['name'])?> · <?=h(role_label($user['role']))?></p></div><div class="user"><?=h($user['email'])?></div></div><?php if($error):?><div class="msg err"><?=h($error)?></div><?php endif;?><?php if($success):?><div class="msg ok"><?=h($success)?></div><?php endif;?>
<?php if($page==='dashboard'):?><div class="grid"><div class="card"><div class="muted">کلاس‌ها</div><div class="stat"><?=count($classes)?></div></div><?php if(manager($user)):?><div class="card"><div class="muted">دانش‌آموزان مرتبط</div><div class="stat"><?=count($students)?></div></div><div class="card"><div class="muted">درخواست‌های ورود</div><div class="stat"><?=count($requests)?></div></div></div><div class="card"><h2>شروع سریع ⚡</h2><div class="actions"><a class="btn" href="<?=pg('create_class')?>">ساخت کلاس</a><a class="btn secondary" href="<?=pg('create_access')?>">دادن دسترسی مستقیم</a></div></div><?php else:?></div><div class="card"><a class="btn" href="/join">ورود به کلاس</a></div><?php endif;?>
<?php elseif($page==='create_student'):?><div class="card"><h2>ساخت حساب دانش‌آموز</h2><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="create_student"><div class="fields"><div><label>نام</label><input name="name" required></div><div><label>ایمیل</label><input name="email" type="email" required></div><div><label>رمز عبور</label><input name="password" type="password" minlength="8" required></div></div><button class="btn" style="margin-top:13px">ساخت</button></form></div>
<?php elseif($page==='students'):?><div class="card"><p class="muted">فقط دانش‌آموزانی که با کلاس‌های این مدرس ارتباط دارند یا توسط خود او ساخته شده‌اند نمایش داده می‌شوند.</p><div class="actions"><a class="btn" href="<?=pg('create_student')?>">+ ساخت دانش‌آموز</a></div><div class="table"><table><tr><th>نام</th><th>ایمیل</th></tr><?php foreach($students as $s):?><tr><td><?=h($s['name'])?></td><td><?=h($s['email'])?></td></tr><?php endforeach;?></table></div></div>
